// 'Thick Skinned' is now fully automated by the feature's Active Effect
// (system.attributes.naturalArmorTier.value = 1), so the -d2 applies the moment
// the feature is gained, unarmored, with no manual equip step. The old approach
// granted a separate 'Thick Skin' armor item; that item is now redundant
// (getCharacterArmorFormula() takes max(wornTier, naturalArmorTier), so it never
// stacked anyway). Clean up any legacy copy so the sheet doesn't show a phantom.
const legacy = actor.items.filter(item => item.name === 'Thick Skin' && item.type === 'armor');
if (legacy.length) {
 await actor.deleteEmbeddedDocuments('Item', legacy.map(item => item.id));
}
